      while (queue.size > 0) {
        const task = queue.dequeue();

        if (this.running >= this.concurrency) {
          await new Promise(resolve => {
            const interval = setInterval(() => {
              if (this.running < this.concurrency) {
                clearInterval(interval);
                resolve();
              }
            }, 10);
          });
        }

        this.running++;
        await executeTask(task);
        this.running--;
      }
    };

    await runTasks();
    return this.results;
  }
