      const startNext = () => {
        while (running < this.concurrency && pq.size > 0) {
          const task = pq.dequeue();
          running++;
          this._runTask(task).then((res) => {
            results.push(res);
            running--;
            checkDone();
            startNext();
          });
        }
      };

      startNext();
    });

    await allDone;
    return results;
  }

  async _runTask(task) {
    let attempts = 0;
    while (true) {
